import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D_TdfPur.js";const m=JSON.parse(`{"title":"Articles","description":"Longer reads about michi-chat from the maker's blog: the reasoning behind the features, written for curious readers.","frontmatter":{"description":"Longer reads about michi-chat from the maker's blog: the reasoning behind the features, written for curious readers.","head":[["link",{"rel":"canonical","href":"https://beany-vu.github.io/michi-chat/articles"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"michi-chat"}],["meta",{"property":"og:title","content":"Articles"}],["meta",{"property":"og:description","content":"Longer reads about michi-chat from the maker's blog: the reasoning behind the features, written for curious readers."}],["meta",{"property":"og:url","content":"https://beany-vu.github.io/michi-chat/articles"}],["meta",{"property":"og:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"michi-chat: a chat assistant platform for small businesses, with the Michi cat crest"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Articles"}],["meta",{"name":"twitter:description","content":"Longer reads about michi-chat from the maker's blog: the reasoning behind the features, written for curious readers."}],["meta",{"name":"twitter:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}]]},"headers":[],"relativePath":"articles.md","filePath":"articles.md"}`),r={name:"articles.md"};function i(h,e,s,c,l,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h1><p>Longer reads about michi-chat from the maker&#39;s blog - the story and the reasoning behind the features, written for curious readers rather than as reference.</p><h2 id="introducing-michi-chat" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/introducing-michi-chat" target="_blank" rel="noreferrer">Introducing michi-chat</a> <a class="header-anchor" href="#introducing-michi-chat" aria-label="Permalink to &quot;[Introducing michi-chat](https://hoang.body-and-binary.net/blog/introducing-michi-chat)&quot;">​</a></h2><p><em>2026-08-30.</em> What the assistant does and why it exists: one instance serving many small businesses, each with its own persona, knowledge and tools - and why the whole platform stayed small enough to read in an afternoon.</p><h2 id="how-michi-chat-works" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/how-michi-chat-works" target="_blank" rel="noreferrer">How michi-chat works</a> <a class="header-anchor" href="#how-michi-chat-works" aria-label="Permalink to &quot;[How michi-chat works](https://hoang.body-and-binary.net/blog/how-michi-chat-works)&quot;">​</a></h2><p><em>2026-08-31.</em> The journey of one question through the system: guardrails, the semantic cache, the tool loop, and why the model layer is a LiteLLM proxy - so swapping the AI model is a config edit, not a rewrite. No AI background needed.</p><h2 id="teach-the-bot-from-a-pdf-without-burning-tokens" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-pdf-import" target="_blank" rel="noreferrer">Teach the bot from a PDF, without burning tokens</a> <a class="header-anchor" href="#teach-the-bot-from-a-pdf-without-burning-tokens" aria-label="Permalink to &quot;[Teach the bot from a PDF, without burning tokens](https://hoang.body-and-binary.net/blog/michi-chat-pdf-import)&quot;">​</a></h2><p><em>2026-09-02.</em> The design story behind the PDF import: the free work happens first, the paid work shows its price before it runs, and why a dirty PDF&#39;s real cost was never the tokens. The hands-on version is the <a href="./owner/import-a-pdf">Turn a PDF into knowledge</a> tutorial here in the docs.</p><h2 id="the-baiting-weekend" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-the-baiting-weekend" target="_blank" rel="noreferrer">The baiting weekend</a> <a class="header-anchor" href="#the-baiting-weekend" aria-label="Permalink to &quot;[The baiting weekend](https://hoang.body-and-binary.net/blog/michi-chat-the-baiting-weekend)&quot;">​</a></h2><p><em>2026-09-06.</em> What strangers tried on a cafe bot, the two places it bent, and why the real fix was observability: store the refusals, flag the conversation, label every turn with how it was produced. Also why visitor IPs are still not stored.</p><h2 id="ten-minutes-a-week" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-ten-minutes-a-week" target="_blank" rel="noreferrer">Ten minutes a week</a> <a class="header-anchor" href="#ten-minutes-a-week" aria-label="Permalink to &quot;[Ten minutes a week](https://hoang.body-and-binary.net/blog/michi-chat-ten-minutes-a-week)&quot;">​</a></h2><p><em>2026-09-06.</em> The owner&#39;s loop: the Unanswered report, the answer-cache inspector, Slack pings, and the retention setting, as a habit rather than a feature list.</p><h2 id="a-second-kind-of-tenant" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-a-second-kind-of-tenant" target="_blank" rel="noreferrer">A second kind of tenant</a> <a class="header-anchor" href="#a-second-kind-of-tenant" aria-label="Permalink to &quot;[A second kind of tenant](https://hoang.body-and-binary.net/blog/michi-chat-a-second-kind-of-tenant)&quot;">​</a></h2><p><em>2026-09-06.</em> Why a chess coach could not run on a platform that refuses everything but the business, why a plugin and a fork were both wrong, and the one-column change that was the right size.</p><h2 id="one-cobalt-line-on-the-roof" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-one-cobalt-line-on-the-roof" target="_blank" rel="noreferrer">One cobalt line on the roof</a> <a class="header-anchor" href="#one-cobalt-line-on-the-roof" aria-label="Permalink to &quot;[One cobalt line on the roof](https://hoang.body-and-binary.net/blog/michi-chat-one-cobalt-line-on-the-roof)&quot;">​</a></h2><p><em>2026-09-06.</em> A design brief in one photograph, applied as a system: the roofline, the two-pixel radius, one black primary per view, and screenshots as the only verification that counts.</p><h2 id="three-small-things-that-make-a-cafe-bot-feel-finished" tabindex="-1"><a href="https://hoang.body-and-binary.net/blog/michi-chat-small-things-that-finish-a-bot" target="_blank" rel="noreferrer">Three small things that make a cafe bot feel finished</a> <a class="header-anchor" href="#three-small-things-that-make-a-cafe-bot-feel-finished" aria-label="Permalink to &quot;[Three small things that make a cafe bot feel finished](https://hoang.body-and-binary.net/blog/michi-chat-small-things-that-finish-a-bot)&quot;">​</a></h2><p><em>2026-09-06.</em> Tappable contact details, a glossary under the analytics bars, and staff logins that see only their own tenant. Why the finished feeling of a product lives in the seams, and the guards that mattered: digit counting so prices never become phone links, a <code>returns</code> sentence no tool pack can skip, and a scope enforced in the queries rather than the menu.</p><hr><p>New posts land on <a href="https://hoang.body-and-binary.net/blog" target="_blank" rel="noreferrer">the blog</a> first and get linked here when they&#39;re about michi-chat.</p>',20)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
